contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function with inputs: amount to deposit, amount to try to collect
    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "need funds to deposit");

        // ensure MinSum and LogFile are settable before Initialized is called
        // set MinSum to 0 so deposit alone makes balance >= MinSum unless set otherwise by external actor
        c.SetMinSum(0);

        // deposit depositAmt into c as this contract (InvMutTest) via c.Deposit
        c.Deposit{value: depositAmt}();

        // read observable before-values
        uint bal_before = c.balances(address(this));
        uint c_bal_before = address(c).balance;

        // attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint bal_after = c.balances(address(this));
        uint c_bal_after = address(c).balance;

        // General rule: if Collect succeeded then both the mapping balance and contract balance
        // decreased by exactly collectAmt; if Collect reverted then both remained unchanged.
        // assert expresses that relation using only public getters and revert flag.
        assert(
            reverted
            ? (bal_after == bal_before && c_bal_after == c_bal_before)
            : (bal_before >= collectAmt && bal_after + collectAmt == bal_before && c_bal_after + collectAmt == c_bal_before)
        );
    }

    // receive to accept refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: amount to deposit into c, amount to attempt to collect
    function run(uint depositAmt, uint collectAmt) public payable {
        // ensure this test contract has funds to deposit
        require(address(this).balance >= depositAmt, "insufficient test funds");

        // ensure contract C is configurable before it's locked: set MinSum to 0 so Collect may be allowed
        c.SetMinSum(0);

        // deposit depositAmt into c as this contract
        c.Deposit{value: depositAmt}();

        // observe before-values
        uint bal_before = c.balances(address(this));
        uint c_bal_before = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint bal_after = c.balances(address(this));
        uint c_bal_after = address(c).balance;

        // General rule:
        // - If Collect reverted then balances and contract balance remain exactly unchanged.
        // - If Collect succeeded then the caller's public balances decreased by exactly collectAmt
        //   and the contract's Ether balance decreased by at least collectAmt (accounts for possible differences in low-level call behavior).
        assert(
            reverted
            ? (bal_after == bal_before && c_bal_after == c_bal_before)
            : (bal_before >= collectAmt && bal_before == bal_after + collectAmt && c_bal_before >= c_bal_after && c_bal_before >= c_bal_after + 0 && c_bal_before - c_bal_after >= collectAmt)
        );
    }

    // Accept refunds if any
    receive() external payable {}
}

