contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function. We take an amount to set as MinSum, a deposit amount, and a collect amount.
    // The function will initialize MinSum and LogFile address, then deposit funds and attempt Collect.
    // Finally it asserts the relation between a successful Collect (no revert) and the last Log entry observed via c.Log().History and LastMsg getters (public arrays/getters are available).
    function run(address logAddr, uint minSum, uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test ETH");

        // Before any initialization, set MinSum and Log contract, then mark initialized.
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Deposit into c the requested depositAmt
        // ensure we have the ETH here and call Deposit via receive or direct Deposit
        // call Deposit with value
        c.Deposit{value: depositAmt}();

        // Read balance before collect and history length before
        uint balBefore = c.balances(address(this));
        // Query LogFile history length and last message via the public getters on LogFile.
        // We access through c.Log() by reading the public Log variable - but Log is not public in C; however LogFile's History is public so we read from the provided logAddr directly.
        // We must observe c only via its public surface; the only required observation here is c.balances and address(c).balance and the LogFile public getters (logAddr is a parameter pointing to that LogFile contract set earlier).

        // Read history length before
        uint histBefore = LogFile(logAddr).HistoryLength();
        // Above line would fail because no HistoryLength exists; instead use the public getter for array: History(uint) returns Message, so we probe index 0..maybe out-of-range revert. To safely get length we rely on public variable .History() isn't directly length-accessible.
        // Since LogFile in the compilation unit has 'Message[] public History;' Solidity generates a getter 'History(uint)'. But there is no auto getter for length; we cannot read length. Workaround: read LastMsg before and after and compare.

        // So read LastMsg before
        (address lastSenderBefore, uint lastValBefore, string memory lastDataBefore, uint lastTimeBefore) = _readLastMsg(logAddr);

        // Try Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read LastMsg after
        (address lastSenderAfter, uint lastValAfter, string memory lastDataAfter, uint lastTimeAfter) = _readLastMsg(logAddr);

        // If Collect did not revert and conditions allowed the transfer (i.e., balBefore >= minSum and balBefore >= collectAmt), then the contract should have logged a Collect message with our address, amount, and Data == "Collect" as the last message.
        // Otherwise, the LogFile's LastMsg should be unchanged with respect to Sender/Val/Data/Time (i.e., equal to before-values).
        // We assert that equivalence.
        bool expectLogged = (!reverted) && (balBefore >= minSum) && (balBefore >= collectAmt);

        // Compose assertion: if expectLogged then lastAfter matches collect details; else lastAfter equals lastBefore
        assert(
            (expectLogged && lastSenderAfter == address(this) && lastValAfter == collectAmt && _stringsEqual(lastDataAfter, "Collect"))
            || (!expectLogged && lastSenderAfter == lastSenderBefore && lastValAfter == lastValBefore && lastTimeAfter == lastTimeBefore && _stringsEqual(lastDataAfter, lastDataBefore))
        );
    }

    // helper to read LastMsg from the LogFile contract given its address
    // We cannot declare types matching LogFile.Message externally, so we read via the public LastMsg getter which exists: LastMsg() returns (address, string, uint, uint)?
    // In the provided LogFile, LastMsg is public so compiler creates a getter with signature LastMsg() returning (address,string,uint,uint).
    function _readLastMsg(address logAddr) internal view returns (address sender, uint val, string memory data, uint time) {
        // The auto-generated getter order matches the struct fields: Sender, Data, Val, Time
        // But Solidity returns tuple types in that order; we must match types. We'll call LastMsg on the LogFile contract.
        (address Sender, string memory Data, uint Val, uint Time) = LogFile(logAddr).LastMsg();
        return (Sender, Val, Data, Time);
    }

    function _stringsEqual(string memory a, string memory b) internal pure returns (bool) {
        return keccak256(bytes(a)) == keccak256(bytes(b));
    }

    // Allow this test contract to receive ETH for making deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function.
    // Parameters:
    // - logAddr: address of a LogFile contract to set in C
    // - minSum: value to set as MinSum before initializing
    // - depositAmt: amount of ETH to deposit into C
    // - collectAmt: amount to attempt to collect
    // The function is payable only to accept ETH for depositAmt.
    function run(address logAddr, uint minSum, uint depositAmt, uint collectAmt) public payable {
        // ensure this contract has enough ETH to make the deposit
        require(address(this).balance >= depositAmt, "Insufficient test ETH");

        // Configure C before marking it initialized
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Perform Deposit with provided ETH
        c.Deposit{value: depositAmt}();

        // Read caller balance in C before Collect
        uint balBefore = c.balances(address(this));

        // Read LastMsg from the LogFile before Collect. The auto-generated getter for LastMsg
        // has the struct field order: Sender, Data, Val, Time as defined in LogFile.
        (address lastSenderBefore, string memory lastDataBefore, uint lastValBefore, uint lastTimeBefore) = LogFile(logAddr).LastMsg();

        // Try Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read LastMsg after Collect
        (address lastSenderAfter, string memory lastDataAfter, uint lastValAfter, uint lastTimeAfter) = LogFile(logAddr).LastMsg();

        // Expectation: if Collect did not revert and the preconditions for Collect were satisfied
        // (balance before >= MinSum and balance before >= collectAmt) then LogFile.LastMsg must have been updated
        // to (Sender == address(this), Val == collectAmt, Data == "Collect"). Otherwise, LastMsg must remain identical.
        bool hadEnough = (balBefore >= minSum) && (balBefore >= collectAmt);
        bool expectLogged = (!reverted) && hadEnough;

        // Single general assert capturing the rule
        assert(
            (expectLogged && lastSenderAfter == address(this) && lastValAfter == collectAmt && keccak256(bytes(lastDataAfter)) == keccak256(bytes("Collect")))
            || (!expectLogged && lastSenderAfter == lastSenderBefore && lastValAfter == lastValBefore && lastTimeAfter == lastTimeBefore && keccak256(bytes(lastDataAfter)) == keccak256(bytes(lastDataBefore)))
        );
    }

    // Allow this test contract to receive ETH to fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function:
    // logAddr: address of LogFile to set in C
    // minSum: value to set as MinSum before initializing
    // depositAmt: ETH to deposit into C
    // collectAmt: amount to attempt to collect
    function run(address logAddr, uint minSum, uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "not enough ETH for deposit");

        // configure C before initializing
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // perform deposit to ensure balances[msg.sender] may be increased
        c.Deposit{value: depositAmt}();

        // read balance before collect
        uint balBefore = c.balances(address(this));

        // read length of History before collect via public getter History(uint)
        // If History is empty, we treat index 0 access as unavailable, so read length by probing until revert would be problematic.
        // But LogFile exposes History as public array; Solidity generates a getter History(uint) -> (Sender,Data,Val,Time).
        // We will read the last index by using address(c).balance and balBefore to decide a safe index: if History has at least one entry, index 0 exists.
        // To obtain previous last index, attempt to read History(0) to get a baseline and then iterate increasing index until a call reverts is not allowed here.
        // Instead, rely on the fact that if History is empty, reading History(0) will revert — avoid that by using try/catch.

        // Attempt to read index 0 to see if any entries exist, capturing the last-known entry if present
        bool hadAnyBefore = false;
        address prevSender = address(0);
        string memory prevData = "";
        uint prevVal = 0;
        uint prevTime = 0;
        try LogFile(logAddr).History(0) returns (address s, string memory d, uint v, uint t) {
            // There is at least one entry; we need to find the actual last index. We will binary-walk by increasing index until a call reverts is not allowed here.
            // Simpler approach: repeatedly read index 0 and treat it as representative of "some previous entry". Since rule requires last entry unchanged when no log, comparing to index 0 suffices only if History length==1.
            // To make a robust observable, we will read History(0) and also read History( (address(this).balance + balBefore) % 1 + 0 ) which is same. Given limitations, we instead record History(0) as previous and later check last entry equals that when no new log is expected and History length==1. But we must craft assertion to allow cases when History had more than 1 entry: when expecting no new log we assert that some existing entry still equals previous at index 0 OR last entry equals previous if only one.
            hadAnyBefore = true;
            prevSender = s;
            prevData = d;
            prevVal = v;
            prevTime = t;
        } catch {}

        // Try Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After Collect, read the last entry in History by scanning from index 0 upward until an index access reverts is not possible here; so instead we will read index 0 and treat it as "some entry" and also read index  (0) again. Given constraints, we will assert properties that only require reading History(0) and that if Collect succeeded then History(0) must equal the Collect entry (this will hold if LogFile appended to empty array or if only one entry existed). To be more generally correct, we also check History(0) equals prev when no new log expected.
        bool readAnyAfter = false;
        address afterSender = address(0);
        string memory afterData = "";
        uint afterVal = 0;
        uint afterTime = 0;
        try LogFile(logAddr).History(0) returns (address s2, string memory d2, uint v2, uint t2) {
            readAnyAfter = true;
            afterSender = s2;
            afterData = d2;
            afterVal = v2;
            afterTime = t2;
        } catch {}

        // Determine whether Collect should have succeeded in normal semantics: it succeeds (i.e., does not revert) only when balBefore >= minSum and balBefore >= collectAmt and contract call to msg.sender succeeds.
        // We can't observe the internal call success separately from overall reverted flag; but if reverted==false then call succeeded and log appended. So expectation: if reverted==false then last log entry must reflect collect.
        // Build expectLogged flag
        bool expectLogged = !reverted && (balBefore >= minSum) && (balBefore >= collectAmt);

        // Single assert: if expectLogged then History(0) must correspond to Collect (Sender==address(this), Val==collectAmt, Data=="Collect");
        // else History(0) must equal previous History(0) if there was one, or remain absent (readAnyAfter==false && hadAnyBefore==false).
        // This assertion is general over inputs and observable values.
        assert(
            (
                expectLogged
                && readAnyAfter
                && afterSender == address(this)
                && afterVal == collectAmt
                && keccak256(bytes(afterData)) == keccak256(bytes("Collect"))
            )
            || (
                !expectLogged
                && (
                    (hadAnyBefore && readAnyAfter && prevSender == afterSender && prevVal == afterVal && prevTime == afterTime && keccak256(bytes(prevData)) == keccak256(bytes(afterData)))
                    || (!hadAnyBefore && !readAnyAfter)
                )
            )
        );
    }

    receive() external payable {}
 }

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // logAddr: address of LogFile to set in C
    // minSum: MinSum to configure
    // depositAmt: amount to deposit so C.balances(this) may be >= minSum
    // collectAmt: amount to attempt to Collect
    function run(address logAddr, uint minSum, uint depositAmt, uint collectAmt) public payable {
        // ensure we have ETH available to deposit
        require(address(this).balance >= depositAmt, "not enough ETH for deposit");

        // configure C (allowed only before Initialized)
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // perform Deposit to increase this contract's balance in C
        c.Deposit{value: depositAmt}();

        // read balance before Collect
        uint balBefore = c.balances(address(this));

        // attempt to read the last History entry index by probing index 0: either there is an entry at 0 or the call will revert and we catch it
        bool hadEntry0Before = false;
        address prev0_sender = address(0);
        string memory prev0_data = "";
        uint prev0_val = 0;
        uint prev0_time = 0;
        try LogFile(logAddr).History(0) returns (address s, string memory d, uint v, uint t) {
            hadEntry0Before = true;
            prev0_sender = s;
            prev0_data = d;
            prev0_val = v;
            prev0_time = t;
        } catch {}

        // try Collect and record whether it reverted
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read entry at index 0 after Collect (if present)
        bool hasEntry0After = false;
        address after0_sender = address(0);
        string memory after0_data = "";
        uint after0_val = 0;
        uint after0_time = 0;
        try LogFile(logAddr).History(0) returns (address s2, string memory d2, uint v2, uint t2) {
            hasEntry0After = true;
            after0_sender = s2;
            after0_data = d2;
            after0_val = v2;
            after0_time = t2;
        } catch {}

        // The intended general rule:
        // If Collect did not revert, then a new log entry corresponding to the Collect must have been appended.
        // When an entry is appended to an empty array, it appears at index 0. When index 0 existed before, we conservatively allow that the new entry may be at a higher index; however, if index 0 did not exist before then a non-reverting Collect must create index 0 holding the Collect message. To make a provable general property using only Index 0 observations:
        // - If Collect did not revert AND there was no entry at index 0 before, then after there must be an entry at index 0 with Sender==address(this), Val==collectAmt, Data=="Collect".
        // - If Collect reverted, then index 0 (if it existed) must remain unchanged; or if it didn't exist before it must still not exist after.

        // Build the assertion implementing that rule.
        bool loggedIfNew = (!collectReverted && !hadEntry0Before && hasEntry0After
            && after0_sender == address(this)
            && after0_val == collectAmt
            && keccak256(bytes(after0_data)) == keccak256(bytes("Collect")));

        bool unchangedIfReverted = (collectReverted && ((hadEntry0Before && hasEntry0After
            && prev0_sender == after0_sender
            && prev0_val == after0_val
            && prev0_time == after0_time
            && keccak256(bytes(prev0_data)) == keccak256(bytes(after0_data)))
            || (!hadEntry0Before && !hasEntry0After)));

        // The assert encodes the general rule: either the Collect produced the expected new index-0 entry when there was no index-0 before and it didn't revert,
        // or, if Collect reverted, index-0 is unchanged (presence and contents preserved).
        assert(loggedIfNew || unchangedIfReverted);
    }

    receive() external payable {}
}

