    // the template though we don't send Ether here.
    function run(bool doInit, uint newMin, address newLog) public payable {
        // No precondition on parameters
        // Read MinSum and Log before any actions
        uint beforeMin = c.MinSum();
        address beforeLog = address(c.Log());

        // Optionally initialize the contract
        if (doInit) {
            c.Initialized();
        }

