                // and stored values reflect only changes made before init: afterMin equals either beforeMin or newMin
                && (afterMin == beforeMin || afterMin == newMin)
                && (afterLog == beforeLog || afterLog == newLog)
                // additionally, if a pre-init setter reverted then the corresponding value must remain the before value
                && (setMinReverted1 ? (afterMin == beforeMin) : true)
