                initRevertedBefore = false;
            } catch {
                initRevertedBefore = true;
            }
        } else {
            initRevertedBefore = true; // indicates not successfully initialized before the first setters
        }

        // First round: attempt SetMinSum and SetLogFile
        try c.SetMinSum(newMin) {
            setMinRevertedBefore = false;
        } catch {
            setMinRevertedBefore = true;
        }

        try c.SetLogFile(newLog) {
            setLogRevertedBefore = false;
        } catch {
            setLogRevertedBefore = true;
        }

        // If not initialized before, attempt to initialize now
        if (!callInitFirst) {
            try c.Initialized() {
                initRevertedAfter = false;
            } catch {
                initRevertedAfter = true;
            }
        } else {
            // we already attempted init earlier; reflect that in after flag as well
            initRevertedAfter = initRevertedBefore;
        }

        // After initialization attempt, try setters again (these are the "post-init" attempts)
        try c.SetMinSum(newMin + 1) {
            setMinRevertedAfter = false;
        } catch {
            setMinRevertedAfter = true;
        }

        try c.SetLogFile(address(uint160(uint256(keccak256(abi.encodePacked(newLog, uint256(1))))))) {
            setLogRevertedAfter = false;
        } catch {
            setLogRevertedAfter = true;
        }

        // Observe final MinSum (Log is not public-gettable by name so we cannot read it here)
        uint256 afterMin = c.MinSum();

        // Single general assert:
        // If initialization succeeded at some point (either before or after the first setters), then
        // any setter attempted after that successful initialization must have reverted (we check the post-init flags),
        // and the final MinSum must equal either the original beforeMin (if the only successful SetMinSum occured and it reverted or never happened before init)
        // or the value set by a SetMinSum that happened before initialization (we attempted newMin before init). Concretely,
        // when initialization succeeded at least once: post-init SetMinSum/SetLogFile calls must have reverted, and afterMin must be either beforeMin or newMin,
        // and if the pre-init SetMinSum reverted then afterMin must equal beforeMin.
        assert(
            (
                // Case: initialization never succeeded in this run (both init attempts reverted or weren't called successfully)
                (initRevertedBefore && initRevertedAfter)
            ) || (
                // Case: initialization succeeded at least once
                // then post-init setters we attempted must have reverted
                (setMinRevertedAfter == true && setLogRevertedAfter == true)
                // final Min must be either unchanged or equal to the pre-init newMin
                && (afterMin == beforeMin || afterMin == newMin)
                // if the pre-init SetMinSum reverted then final Min must equal beforeMin
                && (setMinRevertedBefore ? (afterMin == beforeMin) : true)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // newMin1, newMin2: values to attempt to set via SetMinSum
    // newLog1, newLog2: addresses to attempt to set via SetLogFile
    // callInitAt: 0 = not call Initialized at all, 1 = call Initialized after first setters, 2 = call Initialized before any setters
    function run(uint256 newMin1, uint256 newMin2, address newLog1, address newLog2, uint8 callInitAt) public payable {
        require(callInitAt <= 2);

        // Observe initial MinSum
        uint256 beforeMin = c.MinSum();

        // Attempt first round of setters (these are top-level calls)
        bool setMin1Reverted;
        bool setLog1Reverted;
        try c.SetMinSum(newMin1) {
            setMin1Reverted = false;
        } catch {
            setMin1Reverted = true;
        }

        try c.SetLogFile(newLog1) {
            setLog1Reverted = false;
        } catch {
            setLog1Reverted = true;
        }

        // Optionally initialize before second round
        bool initReverted;
        if (callInitAt == 2) {
            try c.Initialized() {
                initReverted = false;
            } catch {
                initReverted = true;
            }
        } else {
            initReverted = true; // not initialized yet
        }

        // Second round of setters (attempt after possible initialization)
        bool setMin2Reverted;
        bool setLog2Reverted;
        try c.SetMinSum(newMin2) {
            setMin2Reverted = false;
        } catch {
            setMin2Reverted = true;
        }

        try c.SetLogFile(newLog2) {
            setLog2Reverted = false;
        } catch {
            setLog2Reverted = true;
        }

        // Optionally initialize after second round (if requested)
        bool initRevertedLater;
        if (callInitAt == 1) {
            try c.Initialized() {
                initRevertedLater = false;
            } catch {
                initRevertedLater = true;
            }
        } else {
            initRevertedLater = true;
        }

        // Final observed MinSum
        uint256 afterMin = c.MinSum();

        // Determine whether initialization succeeded at any point
        bool initSucceeded = (!initReverted) || (!initRevertedLater);

        // Single general assert:
        // If initialization succeeded at some point, then any setter attempted after that successful initialization must have reverted;
        // and the final MinSum must equal either the value set by a SetMinSum that succeeded before initialization (if any), or the original beforeMin.
        // We can observe which SetMinSum succeeded before initialization: if init was called before second round (callInitAt==2) then only the first round is pre-init,
        // else if init called after second round (callInitAt==1) then both first and second round are pre-init; if no init then none are pre-init.

        // Identify whether a SetMinSum succeeded before initialization according to call ordering and revert flags
        bool preInitSetMinSucceeded;
        uint256 preInitValue;

        if (callInitAt == 2) {
            // init before any setters: no pre-init setters
            preInitSetMinSucceeded = false;
            preInitValue = beforeMin;
        } else if (callInitAt == 1) {
            // init after both rounds: both rounds are pre-init
            // A pre-init successful SetMin is any of the two that did not revert; the later one (second) would overwrite first
            if (!setMin2Reverted) {
                preInitSetMinSucceeded = true;
                preInitValue = newMin2;
            } else if (!setMin1Reverted) {
                preInitSetMinSucceeded = true;
                preInitValue = newMin1;
            } else {
                preInitSetMinSucceeded = false;
                preInitValue = beforeMin;
            }
        } else {
            // callInitAt == 0 -> never initialize: no pre-init setters
            preInitSetMinSucceeded = false;
            preInitValue = beforeMin;
        }

        // Now assert the invariant
        assert(
            (
                // If initialization did not succeed at all, we don't enforce post-init revert property here
                !initSucceeded
            ) || (
                // Initialization succeeded: any setter that was attempted after the first successful initialization must have reverted.
                // We conservatively check the setters we performed after init: when callInitAt==2, second round is post-init; when callInitAt==1, none are post-init; when 0 none are post-init.
                (
                    // If init happened before second round (callInitAt==2 and initSucceeded), then both second-round setters must have reverted
                    (callInitAt == 2 ? (setMin2Reverted && setLog2Reverted) : true)
                )
                // And final MinSum must equal the pre-init value (either beforeMin or a pre-init successful SetMinSum)
                && (afterMin == preInitValue)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // newMinA, newMinB: values to attempt to set via SetMinSum
    // newLogA, newLogB: addresses to attempt to set via SetLogFile
    // order: 0 = do not call Initialized at all; 1 = call Initialized after first round; 2 = call Initialized before any setter
    function run(uint256 newMinA, uint256 newMinB, address newLogA, address newLogB, uint8 order) public payable {
        require(order <= 2);

        // Observe initial MinSum
        uint256 beforeMin = c.MinSum();

        // First round of setters (top-level calls)
        bool setMinAReverted;
        bool setLogAReverted;
        try c.SetMinSum(newMinA) {
            setMinAReverted = false;
        } catch {
            setMinAReverted = true;
        }

        try c.SetLogFile(newLogA) {
            setLogAReverted = false;
        } catch {
            setLogAReverted = true;
        }

        // Possibly initialize before second round
        bool initReverted;
        if (order == 2) {
            try c.Initialized() {
                initReverted = false;
            } catch {
                initReverted = true;
            }
        } else {
            initReverted = true; // treat as not successfully initialized yet
        }

        // Second round of setters (top-level calls)
        bool setMinBReverted;
        bool setLogBReverted;
        try c.SetMinSum(newMinB) {
            setMinBReverted = false;
        } catch {
            setMinBReverted = true;
        }

        try c.SetLogFile(newLogB) {
            setLogBReverted = false;
        } catch {
            setLogBReverted = true;
        }

        // Possibly initialize after second round
        bool initRevertedLater;
        if (order == 1) {
            try c.Initialized() {
                initRevertedLater = false;
            } catch {
                initRevertedLater = true;
            }
        } else {
            initRevertedLater = true;
        }

        // Determine if initialization succeeded at any point
        bool initSucceeded = (!initReverted && order == 2) || (!initRevertedLater && order == 1);

        // Read final MinSum
        uint256 afterMin = c.MinSum();

        // Determine the expected MinSum based on which SetMinSum succeeded before the first successful initialization
        // We need to know which SetMin succeeded and whether it was before initialization.

        // Cases:
        // order == 2: init attempted before any setters; so any successful SetMin are post-init and must have reverted -> expected is beforeMin
        // order == 1: init attempted after both rounds; so both rounds are pre-init; the last successful SetMin among A then B (B overrides A) determines expected
        // order == 0: no init attempted; expected is last successful SetMin among A then B (B overrides A)

        bool expectedIsBefore = false;
        uint256 expectedMin = beforeMin;

        if (order == 2) {
            // initialization happened before setters (if it succeeded). If initialization truly succeeded (initSucceeded==true), then no post-init setter may succeed.
            // Whether init actually succeeded is already in initSucceeded. If init did not succeed, then setters are all pre-init and can change MinSum; so we compute by successes.
            if (!initSucceeded) {
                // Both setters are pre-init
                if (!setMinBReverted) {
                    expectedMin = newMinB;
                } else if (!setMinAReverted) {
                    expectedMin = newMinA;
                } else {
                    expectedMin = beforeMin;
                }
            } else {
                expectedMin = beforeMin;
            }
        } else {
            // order == 0 or 1 : initialization (if any) happens after both rounds, so both rounds are pre-init
            if (!setMinBReverted) {
                expectedMin = newMinB;
            } else if (!setMinAReverted) {
                expectedMin = newMinA;
            } else {
                expectedMin = beforeMin;
            }
        }

        // Now assert the general rule:
        // If initialization succeeded, then any setter attempted after the first successful initialization must have reverted.
        // Additionally, the final MinSum equals expectedMin computed from successful pre-init SetMinSum calls (or beforeMin if none).
        // We check post-init setters based on the order variable and which init call succeeded.

        bool postInitSettersReverted;
        if (!initSucceeded) {
            // no post-init setters requirement
            postInitSettersReverted = true;
        } else {
            // If init succeeded and order==2 then second-round setters are post-init; if order==1 then there are no post-init setters we made.
            if (order == 2) {
                postInitSettersReverted = (setMinBReverted && setLogBReverted);
            } else {
                postInitSettersReverted = true;
            }
        }

        assert(postInitSettersReverted && afterMin == expectedMin);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // aMin, bMin: two candidate MinSum values we will try to set in order
    // aLog, bLog: two candidate LogFile addresses we will try to set in order
    // initPos: 0 = call Initialized() before any setters; 1 = call Initialized() between rounds; 2 = call Initialized() after all setters (or not at all)
    function run(uint256 aMin, uint256 bMin, address aLog, address bLog, uint8 initPos) public payable {
        require(initPos <= 2);

        // Observe initial MinSum
        uint256 beforeMin = c.MinSum();

        // If initPos == 0, call Initialized() first
        bool init0Reverted;
        if (initPos == 0) {
            try c.Initialized() {
                init0Reverted = false;
            } catch {
                init0Reverted = true;
            }
        } else {
            init0Reverted = true;
        }

        // First round setters: try SetMinSum(aMin) and SetLogFile(aLog)
        bool setMinAReverted;
        bool setLogAReverted;
        try c.SetMinSum(aMin) {
            setMinAReverted = false;
        } catch {
            setMinAReverted = true;
        }

        try c.SetLogFile(aLog) {
            setLogAReverted = false;
        } catch {
            setLogAReverted = true;
        }

        // If initPos == 1, call Initialized() now
        bool init1Reverted;
        if (initPos == 1) {
            try c.Initialized() {
                init1Reverted = false;
            } catch {
                init1Reverted = true;
            }
        } else {
            init1Reverted = true;
        }

        // Second round setters: try SetMinSum(bMin) and SetLogFile(bLog)
        bool setMinBReverted;
        bool setLogBReverted;
        try c.SetMinSum(bMin) {
            setMinBReverted = false;
        } catch {
            setMinBReverted = true;
        }

        try c.SetLogFile(bLog) {
            setLogBReverted = false;
        } catch {
            setLogBReverted = true;
        }

        // If initPos == 2, call Initialized() now
        bool init2Reverted;
        if (initPos == 2) {
            try c.Initialized() {
                init2Reverted = false;
            } catch {
                init2Reverted = true;
            }
        } else {
            init2Reverted = true;
        }

        // Determine whether initialization succeeded at any of the three attempts
        bool initSucceeded = (!init0Reverted && initPos == 0) || (!init1Reverted && initPos == 1) || (!init2Reverted && initPos == 2);

        // Read final MinSum
        uint256 afterMin = c.MinSum();

        // Compute which SetMinSum calls occurred before the first successful initialization.
        // We consider the timeline: (possible init0) -> setMinA -> (possible init1) -> setMinB -> (possible init2)
        // If an initialization succeeded at a given point, any subsequent setter must have reverted.

        // Determine index of first successful init: 0 (before A), 1 (between A and B), 2 (after B), or 3 (none)
        uint8 firstInitStage = 3;
        if (!init0Reverted && initPos == 0) {
            firstInitStage = 0;
        } else if (!init1Reverted && initPos == 1) {
            firstInitStage = 1;
        } else if (!init2Reverted && initPos == 2) {
            firstInitStage = 2;
        }

        // Determine which SetMinSum success should determine final MinSum: the last successful SetMinSum that occurred before firstInitStage
        uint256 expectedMin = beforeMin;
        if (firstInitStage == 0) {
            // init before any setters => no setter is allowed
            expectedMin = beforeMin;
        } else if (firstInitStage == 1) {
            // init occurred between A and B => only SetMinSum(aMin) can take effect if it succeeded
            if (!setMinAReverted) {
                expectedMin = aMin;
            } else {
                expectedMin = beforeMin;
            }
        } else if (firstInitStage == 2) {
            // init after both rounds => both SetMinSum calls are before init, so last successful of B then A decides (B overrides A)
            if (!setMinBReverted) {
                expectedMin = bMin;
            } else if (!setMinAReverted) {
                expectedMin = aMin;
            } else {
                expectedMin = beforeMin;
            }
        } else {
            // no init succeeded: all setters are allowed; last successful of B then A decides
            if (!setMinBReverted) {
                expectedMin = bMin;
            } else if (!setMinAReverted) {
                expectedMin = aMin;
            } else {
                expectedMin = beforeMin;
            }
        }

        // Additionally, if initialization succeeded at some stage, any setter executed after that stage must have reverted.
        bool postInitSettersWereReverted = true;
        if (firstInitStage == 0) {
            // both A and B are after init and must have reverted
            if (setMinAReverted && setLogAReverted && setMinBReverted && setLogBReverted) {
                postInitSettersWereReverted = true;
            } else {
                postInitSettersWereReverted = false;
            }
        } else if (firstInitStage == 1) {
            // A is before init, B is after init
            if (setMinBReverted && setLogBReverted) {
                postInitSettersWereReverted = true;
            } else {
                postInitSettersWereReverted = false;
            }
        } else if (firstInitStage == 2) {
            // both A and B are before init -> no post-init setters in our sequence
            postInitSettersWereReverted = true;
        } else {
            // no init succeeded -> nothing must have reverted due to init
            postInitSettersWereReverted = true;
        }

        // Final assertion: if init succeeded then post-init setters reverted, and final MinSum equals the expectedMin computed from pre-init successes.
        assert((!initSucceeded && afterMin == expectedMin) || (initSucceeded && postInitSettersWereReverted && afterMin == expectedMin));
    }

    receive() external payable { }
}

