        require(address(this).balance >= depositAmt + extraDeposit);

        // initial history length
        uint histBefore = c.Log().historyCount();

        // set MinSum and initialize Log via provided public functions (only allowed before Initialized)
        // Use calls directly; they will revert if contract already initialized but fresh c is provided.
        c.SetMinSum(minSum);
        c.SetLogFile(address(c.Log()));

