        assert(
            (!collectReverted && balBefore >= minSum && balBefore >= collectAmt
                && balAfter + collectAmt == balBefore
                && contractBalBefore >= contractBalAfter && contractBalBefore - contractBalAfter >= collectAmt
                && histAfter == histBefore + 1)
            || (collectReverted
                && balAfter == balBefore
                && contractBalAfter == contractBalBefore
                && histAfter == histBefore)
        );
    }

    // Provide receive so contract can hold and forward ETH if needed
    receive() external payable {}
}

