contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: params set up balances and invoke Collect
    function run(address depositor, uint depositAmount, uint collectAmount, address logAddr) public payable {
        require(depositor != address(0));
        // Need some Ether to forward when calling Deposit/Collect
        // Ensure this contract has enough balance to deposit and to cover collect if sent back
        require(address(this).balance >= depositAmount + 1);

        // Initialize C: set MinSum and Log and mark initialized so later calls behave normally
        // These calls change c state and must be top-level statements
        c.SetMinSum(1);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Act as depositor by calling Deposit from this contract but through C's public getter we can only observe balances
        // Because msg.sender for calls from this test is the test contract, simulate depositor by using the depositor param
        // However, we cannot change msg.sender arbitrarily. So instead ensure invariant about this contract's balance/log after Collect.
        // To make Deposit attribute to this test contract, we call Deposit and consider balances of this contract (address(this)).

        // Make an initial deposit from this contract
        c.Deposit{value: depositAmount}();

        // Read before values
        uint beforeBal = c.balances(address(this));
        uint beforeCbal = address(c).balance;

        // Read LogFile state via the public History array and LastMsg through getter functions of LogFile are not directly available from C.
        // But C.Log is public? No, Log is of type LogFile but not public; however LogFile.History is public and can be accessed via its address.
        // We set LogFile address earlier (logAddr). Use the LogFile interface by treating address as LogFile and calling History and LastMsg getters.
        LogFile lf = LogFile(logAddr);
        uint beforeHistoryLen = lf.History.length;
        (address beforeLastSender, string memory beforeLastData, uint beforeLastVal, uint beforeLastTime) = _safeLast(lf, beforeHistoryLen);

        // Call Collect for some amount and capture revert
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint afterBal = c.balances(address(this));
        uint afterCbal = address(c).balance;
        uint afterHistoryLen = lf.History.length;
        (address afterLastSender, string memory afterLastData, uint afterLastVal, uint afterLastTime) = _safeLast(lf, afterHistoryLen);

        // ASSERT: If Collect succeeded then either no withdrawal happened (because preconditions failed) - but in that case Collect would have reverted.
        // We assert: if not reverted and history grew by 1 then the last message must be from this contract with Data == "Collect" and Val == collectAmount;
        // if reverted then history length and last message must be unchanged.
        assert(
            (!reverted && afterHistoryLen == beforeHistoryLen + 1 && afterLastSender == address(this) && keccak256(bytes(afterLastData)) == keccak256(bytes("Collect")) && afterLastVal == collectAmount)
            || (reverted && afterHistoryLen == beforeHistoryLen && afterLastSender == beforeLastSender && keccak256(bytes(afterLastData)) == keccak256(bytes(beforeLastData)) && afterLastVal == beforeLastVal)
        );
    }

    // helper to safely get last message fields; since History is public, getter signature is (uint)->(address,string,uint,uint)
    function _safeLast(LogFile lf, uint len) internal view returns (address, string memory, uint, uint) {
        if (len == 0) {
            return (address(0), "", 0, 0);
        } else {
            return lf.History(len - 1);
        }
    }

    receive() external payable {}
}

// Minimal external declarations matching the existing contracts' public getters so Solidity compiles
abstract contract LogFile {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    function History(uint) public view virtual returns (address, string memory, uint, uint) {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // depositor is not used as msg.sender cannot be changed; we operate as this contract
    // depositAmount funds Deposit; collectAmount is passed to Collect
    function run(uint depositAmount, uint collectAmount, address logAddr) public payable {
        require(address(this).balance >= depositAmount, "need funds to deposit");
        require(logAddr != address(0), "log addr");

        // initialize C: set MinSum and Log and mark initialized
        c.SetMinSum(1);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Make a deposit from this contract so balances can permit Collect
        c.Deposit{value: depositAmount}();

        // Observe LogFile History length and last entry (if any) via public getter of LogFile
        // History is a public array, accessible as a function History(uint) returns (address,string,uint,uint)
        // We cannot get .length directly; instead probe increasing indices until out-of-bounds would revert is not allowed.
        // But we can get previous last by iterating conservatively up to a cap. To remain general and avoid loops, we read index 0 and rely on History possibly being empty.
        // Safer approach: read index 0 and treat same-before/after check: We'll record whether History[0] exists by attempting a call.

        // Try to read History[0]
        bool had0 = true;
        address prev0Sender = address(0);
        string memory prev0Data = "";
        uint prev0Val = 0;
        uint prev0Time = 0;
        // Call the external contract's getter in a try/catch fashion via low-level call to avoid needing a LogFile type
        (bool ok0, bytes memory ret0) = logAddr.call(abi.encodeWithSignature("History(uint256)", 0));
        if (ok0 && ret0.length >= 32) {
            // decode: (address,string,uint,uint)
            // decoding string may be tricky if empty; but abi.decode will handle
            (prev0Sender, prev0Data, prev0Val, prev0Time) = abi.decode(ret0, (address, string, uint, uint));
        } else {
            had0 = false;
        }

        // Now call Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, attempt to read History[0] again
        bool had0_after = true;
        address after0Sender = address(0);
        string memory after0Data = "";
        uint after0Val = 0;
        uint after0Time = 0;
        (bool ok0a, bytes memory ret0a) = logAddr.call(abi.encodeWithSignature("History(uint256)", 0));
        if (ok0a && ret0a.length >= 32) {
            (after0Sender, after0Data, after0Val, after0Time) = abi.decode(ret0a, (address, string, uint, uint));
        } else {
            had0_after = false;
        }

        // Also attempt to read History[1] to detect a newly appended entry at index 1
        bool had1_after = true;
        address after1Sender = address(0);
        string memory after1Data = "";
        uint after1Val = 0;
        uint after1Time = 0;
        (bool ok1a, bytes memory ret1a) = logAddr.call(abi.encodeWithSignature("History(uint256)", 1));
        if (ok1a && ret1a.length >= 32) {
            (after1Sender, after1Data, after1Val, after1Time) = abi.decode(ret1a, (address, string, uint, uint));
        } else {
            had1_after = false;
        }

        // ASSERT: If Collect succeeded then either a new entry exists at index 1 (when there was an index0 before)
        // or at index 0 (when there was no index0 before). That new entry must have Sender == address(this), Data == "Collect", Val == collectAmount.
        // If Collect reverted then the entry at index0 must remain equal to previous state (both existence and contents).

        if (!reverted) {
            // success: require that a new entry appeared
            bool newAt0 = (!had0) && had0_after && after0Sender == address(this) && keccak256(bytes(after0Data)) == keccak256(bytes("Collect")) && after0Val == collectAmount;
            bool newAt1 = (had0 && had1_after && after1Sender == address(this) && keccak256(bytes(after1Data)) == keccak256(bytes("Collect")) && after1Val == collectAmount);
            assert(newAt0 || newAt1);
        } else {
            // reverted: index0 must be unchanged
            if (had0 && had0_after) {
                assert(prev0Sender == after0Sender && keccak256(bytes(prev0Data)) == keccak256(bytes(after0Data)) && prev0Val == after0Val && prev0Time == after0Time);
            } else {
                // both absent
                assert(!had0 && !had0_after);
            }
        }
    }

    receive() external payable {}
}

