        } catch {
            reverted = true;
        }

        // Probe History[0] after the Collect call
        bool had0_after = true;
        address after0Sender = address(0);
        string memory after0Data = "";
        uint after0Val = 0;
        uint after0Time = 0;
        (bool ok0a, bytes memory ret0a) = logAddr.call(abi.encodeWithSignature("History(uint256)", uint256(0)));
        if (ok0a && ret0a.length > 0) {
            (after0Sender, after0Data, after0Val, after0Time) = abi.decode(ret0a, (address, string, uint, uint));
        } else {
            had0_after = false;
        }

        // Probe History[1] after the Collect call to detect an appended entry
        bool had1_after = true;
        address after1Sender = address(0);
        string memory after1Data = "";
