            (after1Sender, after1Data, after1Val, after1Time) = abi.decode(ret1a, (address, string, uint, uint));
        } else {
            had1_after = false;
        }

        // Single assert expressing the property for all inputs
        assert(
            // If Collect reverted: History[0] existence and contents unchanged
            (reverted && (
                (had0_before && had0_after && before0Sender == after0Sender && keccak256(bytes(before0Data)) == keccak256(bytes(after0Data)) && before0Val == after0Val && before0Time == after0Time)
                || (!had0_before && !had0_after)
            ))
            ||
            // If Collect succeeded: there is a new entry equal to (this,"Collect",collectAmount) either at index 0 (if no prior entry)
            // or at index 1 (if there was a prior index0)
            (!reverted && (
                (!had0_before && had0_after && after0Sender == address(this) && keccak256(bytes(after0Data)) == keccak256(bytes("Collect")) && after0Val == collectAmount)
                || (had0_before && had1_after && after1Sender == address(this) && keccak256(bytes(after1Data)) == keccak256(bytes("Collect")) && after1Val == collectAmount)
            ))
        );
    }

    receive() external payable {}
}

