contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint depositAmount, uint collectAmount, address logAddr) public payable {
        require(address(this).balance >= depositAmount, "need funds to deposit");
        require(logAddr != address(0), "log addr");

        // initialize C: set MinSum and Log and mark initialized
        c.SetMinSum(1);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Make a deposit from this contract so balances can permit Collect
        c.Deposit{value: depositAmount}();

        // Probe History length and entry(0) before the Collect call
        // call History(uint) via low-level on logAddr is allowed because LogFile is a separate contract
        // but we must only interact with c via its public surface; probing LogFile is permitted as it's external.
        bool had0_before = false;
        address before0Sender = address(0);
        string memory before0Data = "";
        uint before0Val = 0;
        // try to read History(0)
        (bool ok0, bytes memory ret0) = logAddr.call(abi.encodeWithSignature("History(uint256)", uint256(0)));
        if (ok0 && ret0.length > 0) {
            (before0Sender, before0Data, before0Val) = abi.decode(ret0, (address, string, uint));
            had0_before = true;
        }
        // Similarly probe History(1) existence before to detect current length >=2
        bool had1_before = false;
        (bool ok1, ) = logAddr.call(abi.encodeWithSignature("History(uint256)", uint256(1)));
        if (ok1) had1_before = true;

        // Call Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Probe History(0) and History(1) after the Collect call
        bool had0_after = false;
        address after0Sender = address(0);
        string memory after0Data = "";
        uint after0Val = 0;
        (bool ok0a, bytes memory ret0a) = logAddr.call(abi.encodeWithSignature("History(uint256)", uint256(0)));
        if (ok0a && ret0a.length > 0) {
            (after0Sender, after0Data, after0Val) = abi.decode(ret0a, (address, string, uint));
            had0_after = true;
        }
        bool had1_after = false;
        address after1Sender = address(0);
        string memory after1Data = "";
        uint after1Val = 0;
        (bool ok1a, bytes memory ret1a) = logAddr.call(abi.encodeWithSignature("History(uint256)", uint256(1)));
        if (ok1a && ret1a.length > 0) {
            (after1Sender, after1Data, after1Val) = abi.decode(ret1a, (address, string, uint));
            had1_after = true;
        }

        // Single assert expressing the property for all inputs
        assert(
            // If Collect reverted: History length unchanged for indices 0 and 1 (existence and entry(0) unchanged)
            (reverted && (
                ((had0_before == had0_after) && (!had0_before || (before0Sender == after0Sender && keccak256(bytes(before0Data)) == keccak256(bytes(after0Data)) && before0Val == after0Val)))
                && (had1_before == had1_after)
            ))
            ||
            // If Collect succeeded: there is exactly one new appended entry at the first vacant index
            (!reverted && (
                // If there was no entry 0 before, it must now exist and be our Collect entry
                (!had0_before && had0_after && after0Sender == address(this) && keccak256(bytes(after0Data)) == keccak256(bytes("Collect")) && after0Val == collectAmount)
                // If there was entry0 but no entry1 before, then entry1 must now exist and record our Collect
                || (had0_before && !had1_before && had1_after && after1Sender == address(this) && keccak256(bytes(after1Data)) == keccak256(bytes("Collect")) && after1Val == collectAmount)
                // If there were already >=2 entries before (had1_before==true), then we conservatively require that either entry0 or entry1 changed to reflect an appended Collect
                || (had1_before && (
                    (had0_after && after0Sender == address(this) && keccak256(bytes(after0Data)) == keccak256(bytes("Collect")) && after0Val == collectAmount)
                    || (had1_after && after1Sender == address(this) && keccak256(bytes(after1Data)) == keccak256(bytes("Collect")) && after1Val == collectAmount)
                ))
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // addr is an arbitrary address to act as msg.sender for calls to c (but since
    // the test contract is the caller, this parameter is only used to check getters);
    // amount is Ether to send with Deposit/receive.
    function run(address addr, uint256 amount) public payable {
        require(address(this).balance >= amount, "test contract needs funds");

        // Read initial observable state
        uint beforeBal = c.balances(address(this));
        uint beforeHist = c.Log().HistoryLength();

        // Make sure Log is settable and MinSum can be set before initialization
        // Use the public setters (they may revert if already initialized) — here fresh c so ok
        c.SetMinSum(1);

        // Call Initialized() to flip the initialized flag
        c.Initialized();

        // After initialization: perform Deposit with value `amount`
        c.Deposit{value: amount}();

        // Read state after deposit-after-initialized
        uint afterBalInit = c.balances(address(this));
        uint afterHistInit = c.Log().HistoryLength();

        // Now deploy a fresh observation by calling Collect with 0 to avoid changing balances
        // (Collect may revert if MinSum condition not met; we avoid assuming effect)
        bool collectReverted;
        try c.Collect(0) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // For comparison, we now reset by depositing again (this demonstrates repeated Deposit works)
        // Deposit once more with same amount
        c.Deposit{value: amount}();

        uint afterBalSecond = c.balances(address(this));
        uint afterHistSecond = c.Log().HistoryLength();

        // General asserted rule:
        // 1) After calling Initialized, Deposit with `amount` must increase the caller's balance by exactly `amount` (payable succeeded)
        //    and must append at least one History entry (History length increases by >=1).
        // 2) A second Deposit still increases balance by exactly amount and increases History length again.
        assert(
            afterBalInit == beforeBal + amount
            && afterHistInit >= beforeHist + 1
            && afterBalSecond == afterBalInit + amount
            && afterHistSecond >= afterHistInit + 1
        );
    }

    // Receive to accept refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send some Ether so this contract can call payable functions on c.
    // amount is the Ether to send with Deposit.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "not enough balance to send");

        // Observe before values
        uint beforeBal = c.balances(address(this));
        // History is a public array; its getter is History(uint) returning Message, but its length is accessible via calling History(uint) until revert — not available.
        // Instead observe address(c).balance as proxy for Log additions not directly available; but Log.History length is public (History(uint) exists) so we can probe by trying to read increasing indices until revert to compute length.
        // Compute current History length by probing indices until a revert.
        uint beforeHist = 0;
        // probing up to a reasonable bound (e.g., 256) to determine length
        for (uint i = 0; i < 256; i++) {
            // try to read History[i]; if it reverts, we've reached the length
            (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("Log()"));
            // We cannot directly access nested contract getters via c.Log() because Log is public but returns LogFile; however solidity will create a getter c.Log() returning address of LogFile.
            // So instead call the Log getter then call History on it via low-level calls.
            if (!ok) break;
            address logAddr = abi.decode(data, (address));
            (bool ok2, bytes memory d2) = logAddr.staticcall(abi.encodeWithSignature("History(uint256)", i));
            if (!ok2) break;
            beforeHist++;
        }

        // Set MinSum (allowed before Initialized)
        c.SetMinSum(1);
        // Set LogFile to itself (no-op) - we use c.Log setter to ensure Log is settable before Initialized
        c.SetLogFile(address(c));

        // Initialize the contract
        c.Initialized();

        // Perform Deposit with value amount
        c.Deposit{value: amount}();

        // Observe after values
        uint afterBal = c.balances(address(this));
        uint afterHist = 0;
        // recompute History length as before, probing indices
        for (uint i = 0; i < 256; i++) {
            (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("Log()"));
            if (!ok) break;
            address logAddr = abi.decode(data, (address));
            (bool ok2, ) = logAddr.staticcall(abi.encodeWithSignature("History(uint256)", i));
            if (!ok2) break;
            afterHist++;
        }

        // General rule: after calling Initialized, a Deposit increases caller's reported balance by exactly amount
        // and increases the Log.History length by at least 1.
        assert(afterBal == beforeBal + amount && afterHist >= beforeHist + 1);
    }

    receive() external payable {}
}
